"""Seed all 30 knowledge base entries."""
import sys, os
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from dotenv import load_dotenv
load_dotenv(os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), '.env'))
from database import db

knowledge_col = db["knowledge_base"]

ENTRIES = [
    # ── Indicators (15) ──
    {"term_id":"rsi","term":"RSI (Relative Strength Index)","category":"indicator","short_description":"Measures how fast a stock's price is rising or falling on a scale of 0-100. Below 30 means oversold (might bounce up), above 70 means overbought (might drop).","example":"Reliance RSI drops to 25. This means the stock has been falling hard and might be due for a bounce. A trader might buy here expecting a reversal."},
    {"term_id":"sma","term":"SMA (Simple Moving Average)","category":"indicator","short_description":"The average closing price over a set number of days. Smooths out price noise to show the trend direction.","example":"SMA(50) = average of last 50 days' closing prices. If Infosys is trading at \u20b91,800 and its SMA(50) is \u20b91,750, the stock is above its 50-day average \u2014 a bullish sign."},
    {"term_id":"ema","term":"EMA (Exponential Moving Average)","category":"indicator","short_description":"Like SMA but gives more weight to recent prices. Reacts faster to new price changes.","example":"EMA(20) on TCS moves up sharply after a good earnings report, while SMA(20) reacts slower. Traders who want quicker signals prefer EMA."},
    {"term_id":"macd","term":"MACD (Moving Average Convergence Divergence)","category":"indicator","short_description":"Shows the relationship between two moving averages. When the MACD line crosses above the signal line, it's a buy signal. Below = sell signal.","example":"HDFC Bank's MACD line crosses above its signal line. This 'bullish crossover' suggests upward momentum is building. Many traders use this as a buy trigger."},
    {"term_id":"bollinger","term":"Bollinger Bands","category":"indicator","short_description":"Three lines around the price \u2014 middle (SMA), upper (+2 std dev), lower (-2 std dev). Price touching the lower band often means the stock is temporarily oversold.","example":"SBIN price touches the lower Bollinger Band at \u20b9620 while the middle band is at \u20b9650. This 'lower touch' suggests the stock may be oversold and could bounce back toward \u20b9650."},
    {"term_id":"stochastic","term":"Stochastic Oscillator","category":"indicator","short_description":"Compares a stock's closing price to its price range over a period. Values below 20 = oversold, above 80 = overbought.","example":"ITC's Stochastic %K drops to 15 and then crosses above %D line. This signals the stock may be turning up from an oversold condition."},
    {"term_id":"adx","term":"ADX (Average Directional Index)","category":"indicator","short_description":"Measures how strong a trend is, regardless of direction. ADX above 25 = strong trend. Below 20 = weak/no trend.","example":"Reliance has ADX = 35, meaning it's in a strong trend. A trader would look for trend-following strategies here, not mean-reversion ones."},
    {"term_id":"atr","term":"ATR (Average True Range)","category":"indicator","short_description":"Measures how much a stock typically moves in a day. Higher ATR = more volatile stock. Used to set stop-losses at a safe distance.","example":"Bajaj Finance has ATR(14) = \u20b9120, meaning it typically moves \u20b9120 per day. Setting a stop-loss at \u20b950 would be too tight \u2014 you'd get stopped out by normal daily movement."},
    {"term_id":"supertrend","term":"Supertrend","category":"indicator","short_description":"A trend-following indicator that draws a line above or below the price. When price is above the Supertrend line = uptrend (buy). Below = downtrend (sell).","example":"Supertrend on Infosys flips from red (sell) to green (buy) at \u20b91,780. A trader buys here and holds until Supertrend flips back to red."},
    {"term_id":"vwap","term":"VWAP (Volume Weighted Average Price)","category":"indicator","short_description":"The average price weighted by volume throughout the day. Institutional traders use it as a benchmark. Price above VWAP = bullish, below = bearish.","example":"TCS is trading at \u20b93,900 and today's VWAP is \u20b93,870. Since price is above VWAP, institutional buyers are likely in control. An intraday trader might buy on a VWAP pullback."},
    {"term_id":"pivotpoints","term":"Pivot Points","category":"indicator","short_description":"Key price levels calculated from yesterday's high, low, and close. Used to identify support (S1, S2) and resistance (R1, R2) levels.","example":"Nifty's pivot is 22,500, R1 is 22,650, S1 is 22,350. If Nifty opens above the pivot and breaks R1, traders expect a move toward R2 (22,800)."},
    {"term_id":"psar","term":"PSAR (Parabolic SAR)","category":"indicator","short_description":"Dots placed above or below the price. Dots below = uptrend, dots above = downtrend. When dots switch sides, the trend may be reversing.","example":"Parabolic SAR dots on Maruti are below the candles at \u20b912,400. As long as dots stay below, the uptrend is intact. When dots flip above at \u20b912,600, it signals the uptrend may be ending."},
    {"term_id":"cci","term":"CCI (Commodity Channel Index)","category":"indicator","short_description":"Measures how far the current price deviates from its average. Above +100 = strong uptrend, below -100 = strong downtrend.","example":"Titan's CCI shoots above +100, confirming strong bullish momentum. A trader enters a buy position and exits when CCI drops back below +100."},
    {"term_id":"williams_r","term":"Williams %R","category":"indicator","short_description":"Similar to Stochastic. Measures where today's close is relative to the high-low range. Ranges from 0 to -100. Above -20 = overbought, below -80 = oversold.","example":"Axis Bank's Williams %R is at -85. This extreme oversold reading suggests the stock may be nearing a bottom. A trader watches for it to cross above -80 to confirm a buy."},
    {"term_id":"obv","term":"OBV (On-Balance Volume)","category":"indicator","short_description":"Running total of volume. If price goes up, that day's volume is added. If down, subtracted. Rising OBV with rising price = strong trend.","example":"Kotak Bank price is rising and OBV is also rising \u2014 this confirms the uptrend has real buying behind it, not just a few trades pushing the price."},
    # ── Risk Management (8) ──
    {"term_id":"stop_loss","term":"Stop Loss","category":"risk_management","short_description":"A price level where your trade automatically closes to limit losses. Prevents a small loss from becoming a disaster.","example":"You buy Reliance at \u20b92,500 with a 2% stop loss. If the price drops to \u20b92,450, your position auto-closes. You lose \u20b950 per share instead of potentially \u20b9200+ if it keeps falling."},
    {"term_id":"trailing_sl","term":"Trailing Stop Loss","category":"risk_management","short_description":"A stop loss that moves UP as the stock price rises, locking in profits. It never moves down.","example":"You buy HDFC Bank at \u20b91,600 with a 2% trailing SL. Price rises to \u20b91,700 \u2014 your SL moves to \u20b91,666. If price drops to \u20b91,666, you exit with a \u20b966 profit instead of a loss."},
    {"term_id":"target_profit","term":"Target Profit","category":"risk_management","short_description":"A price level where your trade auto-closes to lock in gains. You decide in advance how much profit is 'enough'.","example":"You buy Infosys at \u20b91,500 with a 5% target. When price hits \u20b91,575, the position auto-closes. You secured your \u20b975 profit without getting greedy."},
    {"term_id":"position_sizing","term":"Position Sizing","category":"risk_management","short_description":"How many shares/lots to buy. Controls how much of your capital is at risk in one trade.","example":"You have \u20b91,00,000 capital. With 'risk 2% per trade' sizing and a \u20b920 stop loss per share, you buy 100 shares (\u20b92,000 max loss = 2% of capital)."},
    {"term_id":"time_exit","term":"Time-Based Exit","category":"risk_management","short_description":"Forces all positions to close at a specific time. Essential for intraday strategies to avoid overnight risk.","example":"Your intraday strategy has a time exit at 3:10 PM. Even if the trade hasn't hit SL or target, it closes before market close at 3:30 PM to avoid overnight gaps."},
    {"term_id":"max_loss_day","term":"Daily Loss Limit","category":"risk_management","short_description":"Maximum total loss allowed in one day across all trades. Once hit, no new trades for the rest of the day.","example":"Your daily loss limit is 3% of capital. After losing \u20b93,000 on a \u20b91,00,000 account, the system stops taking new trades even if there are more signals."},
    {"term_id":"max_trades_day","term":"Max Trades Per Day","category":"risk_management","short_description":"Limits how many trades the strategy can take in a single day. Prevents overtrading.","example":"Max 5 trades per day. Even if your strategy generates 20 signals, only the first 5 are executed. This prevents overtrading during choppy markets."},
    {"term_id":"slippage","term":"Slippage","category":"risk_management","short_description":"The difference between the price you expect and the price you actually get. Happens because markets move between your order and execution.","example":"You place a buy order at \u20b9500 but get filled at \u20b9500.50. That \u20b90.50 is slippage. On 1000 shares, that's \u20b9500 extra cost. Backtests include slippage to show realistic results."},
    # ── General Concepts (7) ──
    {"term_id":"backtest","term":"Backtesting","category":"general","short_description":"Testing your strategy on historical data to see how it would have performed in the past. Does not guarantee future results.","example":"You backtest 'Buy when RSI < 30' on Nifty for the last 3 years. It shows 45 trades, 62% win rate, and 18% total return. Now you have data-driven confidence (not blind hope) before risking real money."},
    {"term_id":"paper_trade","term":"Paper Trading","category":"general","short_description":"Simulating trades with virtual money. Same as real trading but no actual money at risk. Perfect for testing strategies.","example":"You deploy your strategy to paper trading with \u20b910,000 virtual capital. Over 2 weeks, it makes 8 trades and grows to \u20b910,400. Now you know it works on recent data before going live."},
    {"term_id":"equity_curve","term":"Equity Curve","category":"general","short_description":"A graph showing how your capital grows or shrinks over time as trades are executed. Smooth upward = good strategy, jagged = risky.","example":"Your equity curve starts at \u20b91,00,000, dips to \u20b995,000 (drawdown), then climbs to \u20b91,15,000. The dip shows the worst period \u2014 can you handle a \u20b95,000 loss before profits come?"},
    {"term_id":"sharpe_ratio","term":"Sharpe Ratio","category":"general","short_description":"Measures return vs risk. Higher is better. Above 1 = decent, above 2 = great, below 0.5 = risky for the returns you get.","example":"Strategy A returns 20% with Sharpe 1.5. Strategy B returns 25% with Sharpe 0.8. Strategy A is actually better \u2014 it gets nearly the same returns with much less risk."},
    {"term_id":"max_drawdown","term":"Max Drawdown","category":"general","short_description":"The biggest peak-to-bottom drop in your capital during a backtest. Shows the worst-case scenario you might face.","example":"Your strategy's max drawdown is 12%. This means at its worst point, your \u20b91,00,000 account dropped to \u20b988,000 before recovering. Ask yourself: can I stomach a \u20b912,000 temporary loss?"},
    {"term_id":"win_rate","term":"Win Rate","category":"general","short_description":"Percentage of trades that were profitable. A 60% win rate means 6 out of 10 trades made money.","example":"Win rate of 55% sounds low, but if your average win is \u20b9500 and average loss is \u20b9300, you're profitable. Win rate alone doesn't tell the full story \u2014 reward:risk ratio matters too."},
    {"term_id":"profit_factor","term":"Profit Factor","category":"general","short_description":"Total profits divided by total losses. Above 1.0 = profitable. Above 1.5 = good. Above 2.0 = excellent.","example":"Profit factor of 1.8 means for every \u20b91 lost, you made \u20b91.80. Over 100 trades, that compounds into serious gains."},
]

def seed():
    added = 0
    for entry in ENTRIES:
        if not knowledge_col.find_one({"term_id": entry["term_id"]}):
            knowledge_col.insert_one(entry)
            added += 1
    print(f"Seeded {added} new entries. Total: {knowledge_col.count_documents({})}")

if __name__ == "__main__":
    seed()
